insert into public.publishers (exhibitor_no, booth_number, original_booth_number, name, name_en, country_ko, country_en, is_special, categories, introduction, homepage, instagram, sort_order) values
  (1, 'A1001', null, '주식회사 돌베개', 'dolbegae', null, null, false, array['사회과학','역사','기타(청소년)']::text[], '돌베개 출판사는 1979년 창립하여 단단한 책 만들기를 견지해 왔습니다. 우리의 역사와 문화를 조명하는 기획에 관심을 집중하여 ''돌베개 한국학총서''를 비롯한 ''답사여행의 길잡이'', ''테마한국문화사'' 등의 시리즈를 통해 우리의 역사와 문화사상을 대중화하는 데 힘을 쏟아 왔습니다. 엄선된 기획과 내용의 충실함, 깐깐한 편집, 아름다운 디자인을 자랑하며 여러 출판문화상을 수상하였고, 주간지 시사인이 출판전문가들을 대상으로 한 조사에서 다년간 ''가장 신뢰하는 출판사 1위''에 선정되기도 하였습니다. 특별한 콘텐츠를 특별하게 다룬 수십 년의 노력을 기반으로 높은 퀄리티의 도서를 선보이겠습니다. _대표이사 한철희', 'http://dolbegae.co.kr/', 'https://www.instagram.com/dolbegae79/', 1),
  (2, 'A1001', null, '평산책방', 'pyeongsanbooks', null, null, false, array['사회과학','문학','아동']::text[], '대한민국 경남 양산의 시골 마을 작은 책방입니다. 유네스코 세계문화유산인 통도사와 인접해 있어, 사찰의 정적과 평산마을의 평화로운 풍경을 동시에 만끽할 수 있습니다. 단순히 책을 파는 공간을 넘어, 책을 통해 저자와 독자가 만나고 사람이 사람과 연결되는 ''문화 사랑방''을 지향합니다. 재단법인 평산책방에서 운영하고 있으며, 책방의 수익금은 독서 문화 활성화 및 지역사회를 위한 공익사업에 사용됩니다. 문재인 전 대통령이 직접 ''책방지기''로 봉사하며 방문객들을 맞이하기도 합니다. 그가 직접 선정한 추천 도서들을 통해 그의 철학과 취향을 엿볼 수 있습니다. 정갈하게 꾸며진 서가와 책방 마스코트 다봉이와 만복이, 그리고 마당에서 차 한 잔 여유를 즐기며 평화로운 시간을 경험해 보세요.', 'http://www.psbooks.kr', 'https://www.instagram.com/moonjaein/', 2),
  (3, 'A1002', null, '재단법인 아모레퍼시픽재단', 'Amorepacific Foundation', null, null, false, array['기타(인문','자연','과학','예술 분야에 대한 출판 지원)']::text[], '재단법인 아모레퍼시픽재단은 1973년 설립된 기업재단으로, 2025년 아모레퍼시픽공감재단과 통합해 인재육성, 문화예술, 청년지원 분야를 아우르는 공익재단으로 새롭게 도약했습니다. 인문학과 기초학문 지원을 통한 인재 양성, 학문예술 융합 활동 지원, 청년의 마음 건강과 경제적 성장을 위한 커뮤니티 기반 사업을 펼치고 있습니다. 축적된 학술적 깊이와 예술적 감각을 바탕으로 차별화된 문화적 가치를 만들며 아름다움의 가치를 함께 나누는 사회를 지향합니다.', 'https://ascf.amorepacific.co.kr/', null, 3),
  (4, 'A101', null, '고스트북스', 'Ghost Books', null, null, false, array['예술','문학']::text[], '고스트북스는 대구에 자리한 서점 겸 독립출판사로, 국내외 독립출판물과 아티스트북을 소개합니다. 일러스트레이터 류은지와 글을 쓰는 김인철이 함께 운영하며, 출판과 전시, 워크숍, 북토크 등을 통해 책을 매개로 다양한 예술적 실천을 시도합니다. 류은지는 자연의 이야기를, 김인철은 일상성에 유머를 더한 조금은 엉뚱한 상상의 이야기를 쓰며 작업하고 있습니다. 리틀룸은 고스트북스의 세컨 브랜드로, 류은지 작가의 일러스트레이션 작업을 기반으로 한 다양한 제품을 만듭니다. 포스터와 엽서를 비롯해 에코백 등 다양한 상품이 있습니다. 고스트북스는 좋은 영감을 주는 책과 굿즈를 만들고자 합니다. 이를 통해 우리의 작업물이 가닿는 누군가의 삶이 조금은 더 풍성해지기를 기대합니다.', 'https://www.ghostbooks.kr/', 'https://www.instagram.com/ghost__books/', 4),
  (5, 'A102', null, '별빛들', 'BYEOL BIT DEUL', null, null, false, array['문학']::text[], '별빛들은 기존의 구조와 방식으로부터 독립하여 자유롭게 문학 활동하는 작가들과 협업, 그들의 작품집을 소개하여 문학과 출판과의 관계를 유연하게 만들고 문학의 다양화, 출판, 예술의 민주화를 유발하며 나아가 다양한 영역에서 모든 이의 독립되고 자유로운 활동을 응원하고 있습니다. 이러한 철학을 바탕으로 선보이는 별빛들의 도서에서는 한국에서 독립출판으로 문학을 다루는 이들이 누구인지, 그들의 시선을 통해 문학이 어떤 새로운 형태로 확장되는지를 알 수 있습니다.', 'https://byeolbitdeul.com', null, 5),
  (6, 'A103', null, '도서출판부카', 'bookaa', null, null, false, array['총류','철학','종교','사회과학','순수과학','기술과학','공공기관','예술','언어','문학','역사','아동','학습참고서','전자출판','기타']::text[], '대구에서 출판하는 1인 출판사입니다. 아동,청소년을 중심으로 종합 출판을 하고 있습니다. 환경에 관심이 많아 2025년 환경기념일을 주제로 한 52주 52개의 주제로 교재를 출판하였습니다. 항상 새로움을 추구하며 좋은 책, 가치 있는 책을 고민하며 출판을 합니다. 출판 문화 발전에도 관심이 많아 여러가지 활동을 하면서 지속가능한 출판을 해나가는 출판사가 되려고 노력합니다.', 'http://bookaa-n.com', null, 6),
  (7, 'A104', null, '봄봄출판사', 'Bombom Publishing Co.', null, null, false, array['아동']::text[], '그림책 출판사 봄봄은 봄을 본다라는 뜻으로, 어린이와 새싹 그리고 희망을 의미합니다. 따뜻하고 아름다운 그림책을 만들고 싶다는 마음으로 2003년 설립되었습니다. 초심을 늘 간직하면서 책 한 권, 한 권에 마음을 담습니다.', 'http://blog.naver.com/bbpub', null, 7),
  (8, 'A105', null, '단추 출판사', 'Danchu Press', null, null, false, array['사회과학','예술','아동']::text[], '단추는 삶의 이면에 숨겨진 고민의 시간을 소중히 여기며, 사유의 폭을 넓히는 그림책과 예술, 인문서를 만듭니다. 2026년 상반기, 단추는 심해라는 극한의 환경을 통해 세계의 근원과 확장성을 탐구하는 를 비롯해, 폴 콕스, 키티 크라우더 등 동시대 시각 예술가들의 내밀한 작업 세계를 담은 를 통해 창작의 본질에 다가갑니다. 이번 서울국제도서전에서 단추는 심해 연구 포럼과 예술가 라운드 테이블을 통해, 책이라는 물성을 넘어 예술과 과학, 인문학이 교차하는 지점에서의 깊이 있는 담론을 독자들과 나누고자 합니다.', null, 'https://www.instagram.com/danchu_press/', 8),
  (9, 'A106', null, '밝은세상', 'Balgunsesang', null, null, false, array['문학','전자출판']::text[], '밝은세상은 꿈이 가득한 독자, 사랑 가득한 세상이란 슬로건 아래 누구나 쉽고 재밌게 읽을 수 있는 책을 출간하고 있습니다. 독자들과 함께 꿈과 희망을 나누고, 더불어 사는 사회의 향기를 두루 나눌 수 있는 작품을 지향하며 스릴러, 추리, 판타지 등 여러 장르를 통해 긍정적인 독서 경험을 선사하고자 노력합니다. 한 권의 책을 한 번의 호흡으로 몰입해 읽을 수 있다는 경험을 독자에게 선물하고, 이를 발판 삼아 더 많은 책 속 새로운 세상을 넘나들 수 있도록 다양한 책을 펴냅니다. 대표 작가로는 프랑스의 기욤 뮈소, 조엘 디케르, 래티샤 콜롱바니, 미국의 더글라스 케네디, 프리다 맥파든, TJ 클룬, 앨릭스 E. 해로우 등이 있습니다.', null, null, 9),
  (10, 'A107', null, '애플트리테일즈', 'appletreetales', null, null, false, array['예술','아동']::text[], '사과나무 밑에서 꿈을 키워가듯, 애플트리태일즈는 책을 사랑하는 사람들의 위안이 되겠습니다. 건강한 나무가 좋은 결실을 맺듯, 애플트리태일즈는 상상력을 키우고, 꿈과 희망을 주는 건강한 책을 만들어 갑니다. 애플트리태일즈의 책은 비옥한 땅에서 수확한 사과 열매처럼, 튼실하고 따뜻한 콘텐츠로 우리의 영혼을 풍요롭게 합니다. 디지털 시대에도 독자들에게 진정한 위안을 주는 좋은 친구가 되겠습니다!', 'https://www.appletreetales.com/', 'https://www.instagram.com/appletreetales/', 10),
  (11, 'A108', null, '곰세마리', 'Gomsemari', null, null, false, array['문학','아동']::text[], '곰세마리는 30년 넘게 인문철학 분야를 전문으로 출판해 온 그린비출판사의 어린이책 전문 브랜드입니다. 집에서는 가족과, 학교에서는 선생님과 친구와 함께 읽는 책을 모토로, 어린이 독자들이 책을 통해 생각을 나누고 관계 속에서 성장할 수 있는 경험을 만들고자 합니다. 곰세마리는 가족의 이야기를 담은 그림책 시리즈, 자연과 공존을 이야기하는 농부작가 그림책 시리즈와 어린이를 위한 교양 읽기물과 저학년 동화책 등 다양한 주제와 형식의 책을 통해 아이들의 일상과 마음에 가까이 다가가고 있습니다. 책을 읽는 순간에 그치지 않고, 이야기를 나누고 생각을 키우는 과정을 통해 어린이 독자들과 평생 함께 성장하는 관계를 만들어가는 것, 그것이 곰세마리가 지향하는 어린이책입니다.', 'http://greenbee.co.kr', 'https://www.instagram.com/greenbee_publishing/', 11),
  (12, 'A108', null, '도서출판 달리', 'Dahli Children''s Books', null, null, false, array['아동','기타(유아','그림책)']::text[], '도서출판 달리는 2004년에 설립된 어린이 출판사로 지난 20년간 300종이 넘는 어린이책을 출간하였습니다. 대표작으로는 시리즈, , 시리즈 등이 있습니다. 국내 창작 놀이책인 시리즈는 출간 이후 국내에서만 80만부 이상 판매되었습니다. 지난 2022년부터는 국내 창작 그림책을 주력으로 출간하고 있으며, 총 25종의 국내 창작 그림책이 출간되었습니다. , , 을 비롯한 여러 그림책들이 대만, 일본, 중국 등에 수출되었습니다.', null, 'https://www.instagram.com/dahli_books/', 12),
  (13, 'A109', null, '핀드', 'Pinned', null, null, false, array['예술','문학','전자출판']::text[], '''오래 간직할 책, 오래 기억될 이야기''를 만드는 핀드(Pinned)는 등을 편집한 문학 전문 편집자 김선영이 운영하는 1인 출판사로, 한국문학에 생기를 불어넣어주는 작품들로 주목받고 있습니다. 한국 최초 여성 근대 소설가 김명순의 작품을 발굴해 현대에 되살리며 핀드를 시작했고, 장르를 불문한 작가의 첫 단독 저서를 선보이는 시리즈 처음핀드는 믿음직한 라인업으로 자리 잡고 있습니다. 작은 출판사로서 할 수 있는 도전들을 실천하며 의미 있는 책을 만들기 위해 노력하고 있습니다.', 'http://www.pinned.co.kr', null, 13),
  (14, 'A110', null, '소동출판사', 'Sodong Publishing House', null, null, false, array['총류','예술','아동']::text[], '소동은 ''작은 움직임(小動)''이라는 뜻에서 출발했습니다. 왁자지껄 소동의 뜻도 함께 들어있습니다. 소동출판사는 작은 문화의 가치를 중요하게 생각합니다. 작은 것은 눈에 띄진 않지만 잘 가꾸면 어느 날 세상을 바꾸는 힘이 됩니다. 소동출판사는 예술, 생태, 그림책 분야의 책을 주로 발간하고 있습니다. 소동출판사는 새로움, 사람, 지속 가능성에 가치를 둡니다. 우리 자신과 사회를 새로이 바꾸고, 사람을 따뜻하게 해주고, 그것들이 어우러져 평화가 지속되는 세상을 꿈꿉니다. 소동출판사는 저자와 많은 대화를 주고받고, 정성을 다해서 편집과 디자인을 합니다. 독자들의 손때가 오래 묻어나는 책, 독자들의 친구가 되는 책을 만들고자 합니다.', 'http://www.facebook.com/sodongbook', null, 14),
  (15, 'A1101', null, '민음사 출판그룹', 'Minumsa Publishing Group', null, null, false, array['총류','철학','종교','사회과학','순수과학','기술과학','공공기관','예술','언어','문학','역사','아동','학습참고서','전자출판','기타']::text[], '1966년 백성의 소리를 올곧게 담는다.라는 뜻의 민음사가 출판의 첫발을 내디뎠다. 60년간 민음사는 인문학적 가치를 함양하고 젊은 작가를 발굴하기 위해 끊임없이 노력해 왔다. 정확한 번역과 정제된 목록으로 고전의 기준이 된 세계문학전집을 필두로 오르한 파묵, 가즈오 이시구로, 올가 토카르추크 등의 세계적인 작가를 국내에 알렸으며 오늘의 젊은 작가를 통해 한국의 젊은 소설가들을 적극적으로 발굴하고, 세계시인선을 통해 국내 시문학 발전에도 큰 공헌을 했다. 82년생 김지영, 보건교사 안은영 등을 해외에 번역 수출하여 한국문학의 세계화에 일조했다. 또한 제러미 리프킨, 마사 너스바움 등 해외 석학들을 소개하는 한편, 동양 고전을 꾸준히 출간하여 한국 출판의 지적 축대 역할을 하고 있다.', 'http://minumsa.com', null, 15),
  (16, 'A1102', null, '인플루엔셜', 'Influential', null, null, false, array['총류','철학','종교','사회과학','순수과학','기술과학','공공기관','예술','언어','문학','역사','아동','학습참고서','전자출판','기타']::text[], '2013년 시작된 인플루엔셜의 출판사업부에서는 , , , , 등 여러 베스트셀러들을 출간하며 기록적인 행보를 이어가고 있습니다. 2023년엔 한국 소설 브랜드 래빗홀과 어린이 도서 브랜드 북스그라운드 두 개의 임프린트를 성공적으로 론칭하며 출간 분야를 한층 확장했습니다.', 'https://www.influential.co.kr/', null, 16),
  (17, 'A1102', null, '윌라', 'Welaaa', null, null, false, array['총류','철학','종교','사회과학','순수과학','기술과학','공공기관','예술','언어','문학','역사','아동','학습참고서','전자출판','기타']::text[], '윌라는 대한민국 대표 구독형 독서 플랫폼으로, 22만 권 이상의 콘텐츠를 보유하고 있습니다. 전자책, 오디오북, 웹소설, 클래스 등 다양한 콘텐츠를 제공하며, 신간·베스트셀러·독점 도서를 폭넓게 갖추고 있습니다. 또한, 국내 최초로 독서 AI 기술(AI 배속, AI TTS, AI 자막)을 개발·도입했으며, 현재 500만 회 이상의 앱 다운로드를 기록하고 있습니다.', 'https://www.welaaa.com/', 'https://www.instagram.com/welaaa_bookclub/', 17),
  (18, 'A1102', null, '윌라스토리', 'WelaaaStory', null, null, false, array['기타(웹소설)']::text[], '윌라스토리는 2026년 4월 윌라가 론칭한 국내 최초 프리미엄 오디오 웹소설 플랫폼입니다. 팬덤이 검증된 메가 IP를 엄선하고, 국내 정상급 성우의 참여로 오디오 콘텐츠를 직접 제작·편집해 제공합니다. 이를 통해 판타지, 로맨스, 무협 등 기존에 텍스트로 소비되던 웹소설을 오디오로 새롭게 경험할 수 있습니다.', 'https://story.welaaa.com/', 'https://www.instagram.com/welaaa_story/', 18),
  (19, 'A1103', null, '서울특별시 서울도서관', 'Seoul Metropolitan Library', null, null, false, array['기타(도서관)']::text[], '서울도서관은 지식의 문턱을 낮추고 시민의 삶과 꿈을 잇는 서울의 대표 지식문화 공간입니다. 특히 올해 5년 차를 맞은 서울야외도서관은 서울의 새로운 상징으로 자리매김했습니다. 서울광장과 광화문광장, 청계천을 잇는 서울야외도서관은 도심 속에서 독서가 일상이 되는 새로운 문화의 장을 열어 왔습니다. 지난해에는 무려 3,532명의 시민이 한마음으로 참여한 세계 최대 독서 릴레이를 통해 기네스 기록을 달성하는 뜻깊은 성과를 이루었습니다. 또한 2025년 시민이 직접 선정한 서울시 10대 뉴스 1위에 오르며, 시민들의 사랑을 다시 한번 확인했습니다. 서울도서관은 앞으로도 독서가 시민의 자연스러운 일상이 되는 도시를 만들어 가겠습니다. 나아가 서울형 독서모델을 세계와 나누며, 글로벌 지식문화의 거점으로 도약하겠습니다.', 'https://lib.seoul.go.kr/', null, 19),
  (20, 'A1103', null, '신한은행', 'Shinhan Bank', null, null, false, array['총류']::text[], '신한은행은 ''금융의 힘으로 세상을 이롭게 한다'' 라는 미션을 바탕으로 고객과 사회의 가치를 높이는 일에 힘쓰고 있습니다. 또한 전문성을 바탕으로 최적의 금융 솔루션을 제시하여 고객의 자산을 함께 키워가는 자산관리 전문은행입니다.', 'http://www.shinhanbank.com', null, 20),
  (21, 'A111', null, '시사북스(빈페이지)', 'SISABOOKS(emptypage)', null, null, false, array['문학','기타(자기계발','청소년)']::text[], '''무한한 이야기를 담는 공간, 빈페이지''는 무엇이든 담을 수 있는 공백에서 이야기를 시작합니다. 무엇이든 채워질 수 있는 여백이기에 한정되지 않은 서사를 탐색하고, 그 과정에서 아직 쓰이지 않은 이야기의 시작을 발견해 출판으로 연결합니다. 또한 공백에서 시작되는 이야기를 기준으로 서사의 밀도와 감정의 여운을 다듬어 독자의 기억에 남는 이야기를 완성합니다.', 'https://www.sisabooks.com', 'https://www.instagram.com/sisabooks/', 21),
  (22, 'A112', null, '한국출판마케팅연구소', 'KOREA PUBLISH MARKETING', null, null, false, array['총류','철학','종교','사회과학','순수과학','기술과학','공공기관','예술','언어','문학','역사','아동','학습참고서','전자출판','기타']::text[], '한국출판마케팅연구소의 서브컬처 브랜드 요다에서는 장르 소설뿐만 아니라 장르 비평, 스토리텔링에 관한 단행본을 출간합니다. 요다의 대표 도서 회색 인간은 2017년 12월부터 2024년 기준 종이책과 전자책을 합해 약 35만 부 판매를 돌파했고, 현재까지도 많은 독자의 사랑을 받는 스테디셀러로 자리매김 했습니다. 또한 요다의 다양한 작법서는 창작 지망생에게 많은 신뢰를 얻으며 꾸준한 반응을 이어가고 있습니다.', 'https://www.kpm21.co.kr/', 'https://instagram.com/gihoeghoeyi/', 22),
  (23, 'A113', null, '일러스트레이터스 월', 'Illustrators Wall', null, null, true, '{}'::text[], null, null, null, 23),
  (24, 'A1201', null, '타이완콘텐츠진흥원', 'TAICCA', '타이완', 'Taiwan', false, array['총류','철학','종교','사회과학','순수과학','기술과학','공공기관','예술','언어','문학','역사','아동','학습참고서','전자출판','기타']::text[], 'Taiwan Creative Content Agency, established in 2019 by the Ministry of Culture of Taiwan, promotes the development and international expansion of Taiwans cultural and creative industries. TAICCA supports the production, distribution, investment, and marketing of audiovisual content, digital content, music, comics, performing arts, publishing, gaming, immersive content, and more. Through investment programs, co-production initiatives, market intelligence, and global partnerships, TAICCA plays a pivotal role in enhancing the visibility and competitiveness of Taiwans creative industries on the international stage.', 'http://en.taicca.tw', null, 24),
