  (34, 'A1201', null, '타코쿠마', 'TAKOKUMA / Sunthingood Co., Ltd.', '타이완', 'Taiwan', false, array['아동','기타']::text[], 'SUNTHINGOOD은 2014년에 설립되어 브랜드 디자인, 비주얼 기획,크리에이티브 개발을 전문으로 하고 있습니다.탄탄한 디자인 미학과 시장에 대한 깊은 인사이트를 바탕으로, 소비자와감정적으로 연결되고 일상 속에 자연스럽게 스며드는 브랜드 가치를만들어가며 대만 디자인 업계의 주요 참여자로 성장해 왔습니다.2015년부터 IP 개발에 본격적으로 착수하여 오리지널 캐릭터‘타코쿠마(Takokuma)’를 선보였으며, 현재는 일본, 한국, 중국 시장으로확장하여 지속적인 글로벌 전개를 목표로 하고 있습니다.', 'https://takokuma.com/', 'https://www.instagram.com/takokuma/', 34),
  (35, 'A1201', null, '', 'THE GRAYHAWK AGENCY', '타이완', 'Taiwan', false, '{}'::text[], null, null, null, 35),
  (36, 'A1202', null, '주한태국대사관 상무공사관실', 'OFFICE OF COMMERCIAL AFFAIRS, ROYAL THAI EMBASSY, DITP', '태국', 'Thailand', false, array['총류','철학','종교','사회과학','순수과학','기술과학','공공기관','예술','언어','문학','역사','아동','학습참고서','전자출판','기타']::text[], '서울국제도서전 태국관은 저명한 작가와 출판사들이 작품을 선보이고 태국인들의 창의적인 라이프스타일과 사고방식, 정체성을 새롭게 해석하는 작품들을 선보입니다. 태국 작가와 출판사들은 서울국도서전에 참여하여 한국 독자들과 소통하는 시간을 가질 것입니다. 이번 작품은 일상 생활, 문화적 전통, 현대 미술, 문화 공연 서적, 태국어 읽기 및 쓰기 강좌, 태국 소설, 요리책, 도시 풍경에서 영감을 얻은 다채로운 예술적 스타일을 표현한 태국 출판사와 작가들의 서적을 전시할 예정입니다. 이번 행사는 한국 독자들에게 태국 작가와 책을 소개하고, 전통과 현대의 경계를 넘나들며 세계적인 창작자들과 소통하고, 태국 문화적 상상력에 대한 새로운 시각을 제시할 예정입니다.', 'http://www.ditp.go.th', null, 36),
