  (48, 'A1202', null, '모카그룹', 'Mocca Group', '태국', 'Thailand', false, array['총류','철학','종교','사회과학','순수과학','기술과학','공공기관','예술','언어','문학','역사','아동','학습참고서','전자출판','기타']::text[], '모카그룹(Moccagroup)은 우수한 문학 작품을 세계 무대에 선보이는 데 전념하는 선도적인 리터러리 에이전시입니다. 저희는 전 세계의 작가, 출판사, 미디어 파트너를 연결하여 문학 작품의 저작권 수출입, 번역 및 다양한 형식의 2차 저작물 제작을 지원합니다. 모카그룹의 사명은 작가와 스토리텔러들에게 더 넓은 기회를 제공하고, 그들의 작품이 전 세계의 다양한 독자들에게 닿을 수 있도록 가교 역할을 하는 것입니다.', 'http://www.mocca-group.com', null, 48),
  (49, 'A1202', null, '유기적 링크', 'ORGANIC LINKS CO., LTD.', '태국', 'Thailand', false, array['종교','역사']::text[], '유기적 링크 회사는 지속 가능한 발전이라는 개념을 바탕으로 개인과 지역사회의 복지 증진을 위해 설립된 사회적 기업입니다. 개인, 소규모 조직, 대기업을 대상으로 다양한 전략과 도구를 통해 고객의 지속 가능한 발전 목표 달성을 지원하며, 신체적, 정신적 건강 증진에 중점을 두고 있습니다.', 'http://www.organiclinks.co.th', null, 49),
  (50, 'A1202', null, '', 'Silkwormbooks', '태국', 'Thailand', false, '{}'::text[], null, null, null, 50),
  (51, 'A1202', null, '라이터 소울 태국', 'Writer Soul Thailand Corporation Ltd', '태국', 'Thailand', false, array['총류','철학','종교','사회과학','순수과학','기술과학','공공기관','예술','언어','문학','역사','아동','학습참고서','전자출판','기타']::text[], '라이터 소울 태국 ) 유한회사는 작가들이 자신의 이야기를 세상에 내놓을 수 있도록 돕는 종합적인 집필 및 출판 회사입니다.', 'http://Writersoulthailand.com', null, 51),
  (52, 'A1203', null, '', 'EC Publishing LLC', '미국', 'USA', false, '{}'::text[], null, null, null, 52),
  (53, 'A1204', null, '', 'Studio of Books LLC', '미국', 'USA', false, '{}'::text[], null, null, null, 53),
  (54, 'A1205', null, '퀴퍼 프린츠', 'Quipper Prints', '미국', 'USA', false, array['총류','철학','종교','사회과학','순수과학','기술과학','공공기관','예술','언어','문학','역사','아동','학습참고서','전자출판','기타']::text[], 'Quipper Prints is a legally registered publishing and marketing services company based in Nevada. We specialize in helping independent authors self-publish and promote their books through tailored, pay-for-service support. We are not a traditional publisher we do not acquire rights, control royalties, or guarantee sales. Instead, we offer authors full ownership, full royalties, and transparent service packages designed to meet their goals. Our team brings expertise in publishing, branding, design, and digital marketing. Whether youre writing your first manuscript or planning your next promotional campaign, were here to execute with clarity and integrity.', 'http://www.quipperprints.com', 'https://www.instagram.com/quipperprints.us/', 54),
  (55, 'A1206', null, '프로칠레', 'PROCHILE', '칠레', 'Chile', false, array['문학','아동']::text[], 'ProChile은 칠레 외교부 산하 기관으로, 칠레의 상품, 서비스, 투자 기회 및 국가 이미지를 전 세계에 홍보하는 역할을 합니다.이 기관의 주요 중점 분야 중 하나는 시청각 산업, 출판, 비디오 게임, 공연 예술을 포함한 창의 및 문화 산업입니다.출판 분야에서 ProChile은 공공과 민간의 협력을 촉진하고, 볼로냐, 보고타, 프랑크푸르트와 같은 주요 국제 도서전에 참여하여 도서 수출과 지식재산권 판매를 확대하고 있습니다.시장 다변화는 핵심 목표 중 하나로, 이러한 이유로 ProChile은 서울국제도서전에 참가하여 특히 아시아 태평양 지역을 중심으로 새로운 시장 진출을 확대하고자 합니다.', 'http://www.prochile.gob.cl', 'https://www.instagram.com/prochilecl/', 55),
  (56, 'A1206', null, '', 'Calcetines Animados', '칠레', 'Chile', false, '{}'::text[], null, null, null, 56),
  (57, 'A1206', null, '', 'VLP Agency', '칠레', 'Chile', false, '{}'::text[], null, null, null, 57),
  (58, 'A1206', null, '', 'Recrea Libros', '칠레', 'Chile', false, '{}'::text[], null, null, null, 58),
  (59, 'A1207', null, '연변교육출판사', 'Yanbian Education Press', '중국', 'China', false, array['문학','아동','학습참고서','전자출판']::text[], '연변교육출판사는 1947년 3월 24일에 설립되었으며, 현재 조선어문교과서, 초중등학교 교사용도서, 초중등학교 교습 보조도서, 정기간행물, 청소년 독서물 및 기타 문화교육류 도서의 편찬출판을 전문으로 하는 출판사입니다. 2017년 9월 국가 길림민문출판기지 단위 회원이 되었습니다.', 'https://www.ybep.com.cn/', null, 59),
  (60, 'A1207', null, '연변인민출판사', 'Yanbian People''s Press', '중국', 'China', false, array['순수과학','예술','언어','역사','아동','전자출판']::text[], '연변인민출판사는 1951년 8월 19일에 설립되었으며, 민족성 지방성 종합성을 겸비한 공익성 소수민족 출판사입니다. 또한 중국에서 역사가 가장 오래고 규모가 가장 큰 조선어 일반도서와 정기간행물 출판기지입니다.', 'http://www.ybcbs.com', null, 60),
  (61, 'A1207', null, '연변대학출판사', 'Yanbian University Press', '중국', 'China', false, array['문학','아동','학습참고서','전자출판','기타']::text[], '연변대학출판사는 1986년에 설립되었으며 길림성에서 유일한 대학출판사이자 길림성 성급 중점 문화기업입니다. 현재 1개의 지사, 4개의 전액 출자 자회사, 4개의 지주회사, 2개의 잡지사, 6개의 학술잡지를 발행하고 있습니다.', 'http://www.ydcbs.com/', null, 61),
  (62, 'A1301', null, '엣눈북스', 'ATNOONBOOKS', null, null, false, array['예술','문학']::text[], '2014년부터 시작한 작가 중심의 소규모 출판사입니다. 정오의 따사로움과 열정을 담은 책을 만들고자, 엣눈북스라는 이름을 짓게 되었습니다. 일러스트, 사진, 그래픽 아트워크 등 다양한 형태의 시각 이미지와 스토리텔링이 결합한 책을 만들고 있습니다. 끊임없는 시도를 통해 틀을 깨는 경계 없는 이야기를 꿈꿉니다.', 'http://www.atnoonbooks.net', 'https://www.instagram.com/atnoonbooks/', 62),
  (63, 'A1302', null, '서사원 주식회사', 'SEOSAWON', null, null, false, array['사회과학','기술과학','문학']::text[], '''가치 있는 삶을 만드는 지혜로운 콘텐츠'' 서사원 출판사가 지향하는 콘텐츠 방향입니다. 가치 있는 삶은 내 행복이 나에서 그치지 않고 공동체로 뻗어나갈 때 완성됩니다. 훌륭한 콘텐츠는 이런 지향점에 자양분이 된다고 믿습니다. 콘텐츠를 만드는 모두의 마음이 하나로 모아져서 탄생한 콘텐츠가 독자 여러분께 기쁨, 행복, 희망, 비전이 된다는 신념으로 최선을 다해 만들어가고 있습니다.', 'https://seosawonbooks.com/', 'https://www.instagram.com/seosawon/', 63),
  (64, 'A1303', null, '프란츠', 'Franz', null, null, false, array['예술','문학']::text[], '슈베르트의 아름다운 음악에 영감을 받아 그의 이름으로 만든 출판사인 프란츠는 2017년에 책을 펴내기 시작했습니다. 악보집, 악기 교본부터 문학, 인문학 서적에 이르기까지, 음악에 관한 폭넓은 책을 다룹니다. 대표 서적으로는 김애란, 김연수, 윤성희, 은희경, 편혜영 작가가 참여한 『음악소설집』. 파스칼 키냐르의 『음악 혐오』와 『우리가 사랑했던 정원에서』, 필립 글래스의 『음악 없는 말』, 로르 도트리슈의 『역사를 만든 음악가들』, 시미언 피즈 체니의 『야생 숲의 노트』 등이 있습니다. 또한 패션 디자이너 이브 생 로랑의 사업 파트너이자 연인이었던 피에르 베르제가 쓴 편지를 모은 책 『나의 이브 생 로랑에게』를 펴낸 것을 시작으로 다른 예술로의 확장을 시도하고 있습니다.', 'http://franz.kr', 'https://www.instagram.com/franz.kr/', 64),
  (65, 'A1304', null, '귤프레스', 'guulpress', null, null, false, array['기타(만화)']::text[], '귤프레스는 만화가 수신지의 이야기를 책으로 만드는 출판사입니다.', null, 'https://www.instagram.com/guulpress/', 65),
  (66, 'A1305', null, '고요한소리', 'Calm Voice Society', null, null, false, array['종교']::text[], '사단법인 고요한소리는 붓다의 불교, 붓다 당신의 불교를 발굴, 궁구, 실천, 선양하는 것을 목적으로 1987년 설립되었습니다. 지난 30여 년 동안 붓다의 원음이 담긴 빠알리(PLI) 경전과 스리랑카불자협회(Buddhist Publication Society)에서 발간한 불교철학, 심리학, 수행법 등 실생활과 관련된 실천 불교 분야의 책들을 번역 소개해오고 있습니다. 회주이신 활성 스님의 법문집 소리 시리즈를 출간하고, 7회에 걸쳐 중도포럼을 개최하였으며, 붓다의 명상 프로그램, 빠알리 경전 및 불서 읽기 독서 모임을 진행하며 근본불교를 실천하고 널리 알리기 위해 노력하고 있습니다.', 'http://www.calmvoice.org/', null, 66),
  (67, 'A1306', null, '쿵프레스', 'Koong Press', null, null, false, array['아동']::text[], '는 2022년 볼로냐 라가치상 코믹스 부문 대상을 수상하며 세계적으로 인정받은 그림책 작가 이지은이 설립한 출판사입니다. 이지은 작가의 독창적 세계관을 확장하는 외전 및 독후활동 도서를 출간하고, 작품 속 캐릭터와 디자인을 기반으로 한 IP 상품 개발유통을 핵심 사업으로 운영합니다. 또한 보유 IP의 2차 저작권을 바탕으로 공연전시 등 다양한 콘텐츠 사업을 전개하며, 출판과 IP 비즈니스의 다각화를 통해 국내외 시장에서 지속 가능한 성장 모델을 구축하고자 합니다.', 'http://koongpress.com', null, 67),
  (68, 'A1307', null, '한림출판사', 'HOLLYM CORP, PUBLISHERS', null, null, false, array['아동']::text[], '한림출판사는 1977년 미국에 설립한 해외법인 Hollym International Corp.을 통해 한국의 다양한 지식과 정보를 담은 소중한 책을 영어와 각국의 언어로 전 세계에 보급하는 출판 시스템을 구축했으며 국내 어린이 책 시장에 단행본 그림책을 처음 선보이고, 지속적으로 우수한 그림책을 펴내는 등 독보적이고 선구적인 역할로 독자들에게 큰 사랑을 받아 왔습니다. 그림책과 각종 어린이 책을 비롯해 한국어 교재, 한국 사회 문화 예술 분야 전반으로 폭넓게 출판 영역을 확장해 온 성과로 1987년 서울시 문화상, 2000년 한국백상출판문화상 등을 수상했습니다. 창립 60주년을 맞은 한림출판사는 더욱 넓은 세계와 새롭게 펼쳐질 미래를 향한 더 나은 가능성을 꿈꿉니다.', 'https://www.hollym.co.kr', 'https://www.instagram.com/hollymbook/', 68),
  (69, 'A1308', null, '소장각', 'Sojanggak', null, null, false, array['총류','예술','역사']::text[], '소장각은 작은 책들의 집이라는 뜻의 출판사입니다. 우리 주변 가까운 이웃과 친구들의 대화 속에서 반짝이는 독창적인 이야기를 찾아내고, 그것을 아름다운 형태로 엮어 빛나게 하는 것이 소장각의 일입니다. 콘텐츠를 담는 그릇으로서 콘텐츠에 어울리는 책의 꼴을 늘 고민하여 아트북의 관점에서 정성스럽게 제작합니다. 특별히 동남아시아의 시각 문화, 디자인, 생태 중심의 주제를 발굴하여 지역과 독자 사이에서 다리 역할을 하고 있습니다. 책 내용에서 시작해 더 넓게 확장된 다양한 모임과 행사를 함께 진행하면서 책을 넘어 풍성한 이야기의 장을 만들어 가고 있습니다. 동남아시아를 주제로 해외 출판 시장과 교류하며 저작권 수출과 수입, 공동 출판을 함께 이어오고 있습니다.', 'http://sojanggak.kr', 'https://instagram.com/sojanggak/', 69),
  (70, 'A1308', null, '비플랫폼', 'B-PLATFORM', null, null, false, array['예술']::text[], '* 비플랫폼은 책의 예술적 가치를 공유하는 서점,갤러리,스튜디오 공간을 함께 운영하며, 신진작가와 작은 출판사의 전시를 지원합니다. *비플랫폼은 1년에 한 번 B-PLATFORM LAB 프로젝트를 통해 구성된 작가들과 협업하여 시각예술 서적을 중심으로 작품으로서 의미를 갖는 아티스트북을 제작하며 전시와 함께 아티스트토크 이벤트등 일반인에게 소개합니다.', null, 'https://www.instagram.com/bplatform/', 70),
  (71, 'A1309', null, '(주)불광미디어', 'BULKWANG MEDIA', null, null, false, array['철학','종교','아동']::text[], '불광미디어는 1974년 11월 창간된 월간지 을 비롯해서 단행본은 종이책 800여 종을 비롯해 전자책, 오디오북 등 1,000종이 넘는 콘텐츠를 생산한 명실공히 한국을 대표하는 불교 전문 출판사이자 종합 미디어 회사로 매해 성장을 하고 있습니다. 앞으로는 이러한 성장세를 이어나가 콘텐츠로 세계인들과 연결하고 세상을 이롭게 하는 비전으로 주력하려고 합니다.', 'http://www.bulkwang.co.kr', 'https://www.instagram.com/bkbooks79/', 71),
  (72, 'A1310', null, '라의눈주식회사', 'Eye of Ra', null, null, false, array['총류','사회과학','예술']::text[], '"당신은 언제나 옳습니다. 그대의 삶을 응원합니다!" 2014년 설립된 라의눈은 라의눈, 아티젠, 고려원북스, 맛있는잭 등의 브랜드를 통해 약 400여 종의 책을 출간해온 종합출판사입니다. , , , 등의 인문교양서를 통해 지식과 통찰을 전달해왔습니다. , 젠탱글> 시리즈, 인형옷> 시리즈 등 쥐미실용 책도 펴내고 있습니다. , 등 어린이와 정소년을 위한 도서를 꾸준히 출간하고 있습니다', 'http://blog.naver.com/eye_of_ra', null, 72),
  (73, 'A1311', null, '유어마인드', 'YOURMIND', null, null, false, array['예술']::text[], '유어마인드는 2009년부터 작가 개인과 독립출판사에 의해 제작된 독립출판물과 아트북을 전문으로 판매하는 책방입니다. 2017년 서울 연희동으로 이전하여 작은 크기의 책방을 운영하고 있습니다. 동시에 자체 출판물을 제작하고 서울아트북페어 언리미티드 에디션을 매년 주최합니다.', 'https://your-mind.com/', 'https://www.instagram.com/your_mind_com/', 73);
